"""Authored chapter data. Run to write the offline, exported JSON narrative."""
import json
from pathlib import Path

def ev(title,body): return dict(title=title,body=body)
def claim(title,pair,body): return dict(title=title,pair=pair,body=body)
def npc(name,id,topics): return dict(name=name,id=id,topics=topics)
def scene(name,art,people,keys):
    return dict(name=name,art=art,people=people,items=[dict(key=k,x=x,y=y) for k,x,y in zip(keys,[305,1000],[336,362])])
def topic(title,lines): return dict(title=title,lines=lines)
def choice(id,label,lines): return dict(id=id,label=label,lines=lines)
def round_(line,key,reply): return dict(line=line,claim=key,reply=reply)
def bridge(art,name,id,docs,question,options,lines):
    return dict(art=art,name=name,id=id,docs=docs,question=question,options=options,lines=lines)

