 rounds=[round_('“承认不是今天的你，就能说从来没签过？”','oldwrong',[['林砚','不能。甲案授权真实，我保留它。孟岚的当期评估也应调查。'],['孟岚','别因为我愿意作证，就替我擦掉那一页。']]),round_('“系统上都有同一个名字，结果当然一样。”','misuse',[['林砚','乙案由服务账号套用，丙案写的是反对。你们把来源和正文都压平了。'],['闻遥','现在分三卷保存。谁写的、何时写的、写了什么，都在封面。']]),round_('“原型还活着，就由他代表整条链吧。”','identity',[['林砚','他继续生活了五十三年，我们也有自己的经历。同源不产生永久代表权。'],['顾舟','机器能复制状态。代理授权没那么方便。']])],
