 scenes=[scene('分水闸门','waterworks',[npc('祝青',9,[topic('谁先停止供水？',[['祝青','东城守闸人按刻碑关了西渠。双方都在怕对方先抢。'],['林砚','当前水位和用水人口在哪里？'],['祝青','计量台。去看今天的数，别只听祖先争。']]),topic('你代表哪一边？',[['祝青','两边都有我的亲戚。他们都说我该站自己人。'],['林砚','那就把双方能核验的事实放到中间。']])])],['inscription','meters']),scene('教学抄本室','archive',[npc('顾舟',4,[topic('这真是神谕吗？',[['顾舟','原文叫“水阀教程第三题”。技术员给新手练习用的。'],['林砚','后来的历史就因此没有意义了？'],['顾舟','不。几千年真有人照它修渠。教程的出处是真，修出来的城市也是真。']]),topic('被删去的条件在哪？',[['顾舟','页脚被裁掉了。旧纸太长，刻碑的人说放不下。后来掌闸的人发现，少几句话很好用。']])])],['original','revision']),scene('共同计量台','waterworks',[npc('罗荻',11,[topic('是否可以马上全开闸？',[['罗荻','洪峰和供水都要实测。全开可能冲毁西渠，继续全关会让下游断水。'],['林砚','结案不能代替工程判断。'],['罗荻','但能先拆掉“永久独占”的假依据。']]),topic('现实的关停会影响这里吗？',[['罗荻','分水表也依赖共享服务。不是把标着旧项目的插头拔掉就能干净分开。']])])],['petition','dependency'])],
 evidence={'inscription':ev('东城刻碑','“东城控制上游水闸”。无期限、无前提、无双方复核条款。作为永久独占依据使用。'),'meters':ev('双城现行计量','当前非干旱紧急期；西城人口和渠容量均与旧教程设定不同。今天的供给应依据实测，不能机械照搬旧数值。'),'original':ev('教学任务原文','仅在干旱紧急期、且双方共同核验水位后，东城临时操作上游闸门。紧急期结束，恢复共同管理。本页为技术员教学任务。'),'revision':ev('刻碑修订记录','刻碑底稿裁去条件与到期条款；后任掌闸方明知有完整原文，仍以截取版本主张永久权利。'),'petition':ev('双城联合异议书','两城居民共同请求：停止依据删改文本永久锁闸，公开原件，重新协商计量与监督。没有授权侦探替双方分配水量。'),'dependency':ev('运行依赖清单','计量、存储和居民备份共用基础设施。旧城与公共上传服务并非两个可直接拔开的独立系统。')},
