 scenes=[scene('冻结街区','oldquarter',[npc('罗荻',11,[topic('冻结发生时维修员在哪？',[['罗荻','两人在外城，一人在配电间。至少两个根本没有接触调试台。'],['林砚','那张指控名单是怎么来的？'],['罗荻','他们都被排过同一班夜班。']]),topic('被冻结的人会怎样？',[['罗荻','恢复运行的人描述不出暂停时发生什么。外部日志保留了经过的时间。'],['林砚','记录停止，不代表他们失去权利。']])])],['freeze','alibi']),scene('维修机房','server',[npc('邵为',8,[topic('封存后，你为什么还在这里？',[['邵为','我来指认旧操作台，权限没有恢复。监督人在门口。'],['林砚','这次冻结和你有关吗？'],['邵为','冻结不是我触发的。但以前一次冻结期间，我删过一段本地日志。'],['林砚','这条陈述另记，不能用别人的清白掩护它。']]),topic('删除的是哪份记录？',[['邵为','Q-17 的本地副本。我以为独立端也会一起清空。'],['闻遥','没有。它们从来不是同一套保管。']])])],['conflict','deletion']),scene('旧调试间','server',[npc('顾舟',4,[topic('名单为什么用纸保存？',[['顾舟','因为有一次我把“永久保留”选中，系统回了一个永久丢失的错误。'],['林砚','这本名册完整吗？'],['顾舟','能找到的都在这里。有断页，我没有编名字填上。']]),topic('我有过一个孩子？',[['顾舟','旧实例留下的信里有她，叫小满。她四千年前死了。'],['林砚','我读到了那封信，却不能假装记得她的声音。'],['顾舟','知道档案里有一个人，也是一种开始。']])])],['port','names'])],
 evidence={'freeze':ev('三次冻结时间','独立日志：冻结都紧随公司审查握手失败；不是在维修员登录时发生。城市运行暂停，随后由守护程序恢复。'),'alibi':ev('独立门禁与分区日志','被指控的四人中，两人在无法直达调试台的外城，一人在配电间。邵为过去曾在另一次冻结时接触本地日志终端。'),'conflict':ev('协议冲突堆栈','旧调试端口等待外部回执，公司审查端又等待旧端口结束。互相等待导致暂停；应采用只读导出和同步窗口，不能绕过审计直接写入。'),'deletion':ev('本地删除与独立残留','Q-17 本地日志被邵为当期凭据删除，独立端保留调用签名。时间与本次三次冻结不同；这是另一个应追究的动作。'),'port':ev('旧端口接线说明','安全发送顺序：只读镜像 → 双端时钟同步 → 独立审计留痕 → 发送。私人挑战密钥只能验证联系来源，不能授予代表居民的权力。'),'names':ev('被删除者名册与小满的信','顾舟逐年保存姓名、来源与缺页标记。旧林砚给小满的信可核实她曾生活、四千年前死亡；现行林砚读取档案，不会因此拥有全部原记忆。')},
 claims={'fault':claim('冻结来自协议等待冲突',['freeze','conflict'],'冻结时间与冲突栈吻合，修复握手顺序才回应故障，不能按职业抓人。'),'separate':claim('邵为的删除与其他人的指控须分开',['alibi','deletion'],'删除有独立签名和不同时刻。承认这项行为，不等于四个维修员都触发冻结。'),'channel':claim('可以留痕送信，不必抹掉城市记录',['port','names'],'只读与独立保管让通信有证据可验；名册和私人消息不混作同一种授权。')},
