 rounds=[round_('“冻结前有人维修，就是维修员破坏。”','fault',[['林砚','共同出现不等于因果。日志把三次冻结都指向审查端与旧端口的相互等待。']]),round_('“有人承认删日志，那四个人都不用再查。”','separate',[['邵为','删本地副本的是我，另一次。别把这句话写成别人也认了。'],['林砚','分别记录、分别调查。其他人的指控撤去没有依据的部分。']]),round_('“对外传输只能先清掉旧记录腾空间。”','channel',[['顾舟','只读镜像已经接通。空间要申请，名字不该拿来抵账。'],['闻遥','同步和审计都留痕，外部能核对来源，居民也能追问送出了什么。']])],
