 evidence={'current':ev('三名居民当期陈述','林砚 L-now、闻遥 W-now、宋屿 S-new 分别提交今日独立陈述。宋屿是本次表决前已启动的现行居民，不能因恢复较晚被旧备份代替。'),'suppressed':ev('被省略的异议','宋屿的现行反对、闻遥的条件性保留没有进入结果摘要。原始异议仍有提交回执；未答复也不能计为赞成。'),'roll':ev('六条表决票据','0 L-now：今日确认；1 L-old：历史备份；2 W-now：今日确认；3 S-new：今日确认；4 S-old：已终止旧实例；5 W-backup：重复来源备份。'), 'restores':ev('表决时点实例登记','当期独立居民对应 L-now、W-now、S-new。其余三条是历史状态或已终止实例，不能作为今日额外票数；姓名不是去重键。'),'algorithm':ev('签名算法与调用账号','周临批准的批任务从历史备份读取签名，把不同时代的状态重复加入当前计票；缺少当期授权验证，算法未按现行实例去重。'),'attachment':ev('会议附件变更链','原始附件含当前反对与保留意见。周临批准只保留“同意隔离”摘要，之后将该摘要称为全体结果。公开方案仍必须进行真实当期表决。')},
 claims={'duplicate':claim('历史签名被重复算作今日选票',['roll','restores'],'六条票据中只有三条是示例名册里的当期独立陈述。不能把历史副本当作新增居民票。'),'silenced':claim('全体同意省去了当前反对与保留',['current','suppressed'],'原始陈述与回执直接反驳全体同意。恢复有效票不预设某个公共方案必然获胜。'),'responsible':claim('批处理和删附件由周临批准',['algorithm','attachment'],'操作日志与版本链明确责任，资源安全风险不能产生伪造授权的权力。')},
 puzzle=dict(kind='ballot',title='逐票核验 / 谁在今天表达？',instruction='勾选可计入本次统计的当期独立陈述。这里核对的是有效性，不要求他们投赞成。',rows=['0  林砚 L-now / 今日确认','1  林砚 L-old / 历史备份','2  闻遥 W-now / 今日确认','3  宋屿 S-new / 今日确认','4  宋屿 S-old / 已终止','5  闻遥 W-backup / 重复来源备份'],correct=[1,0,1,1,0,0],requires=['roll','restores','current'],hint='当期有效的是 0、2、3。宋屿当前的反对也是有效意愿；历史签名和重复备份不能添票。'),
